// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount, address actor, uint256 unlockTime) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(actor != address(0));
        vm.assume(amount > 0 && amount <= 1e30);
        vm.assume(unlockTime <= 1e12);

        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(unlockTime);

        // General rule: a deposit of `amount` by a fresh holder leaves that holder's
        // balance equal to the deposited amount (balance accumulates deposits).
        (uint256 unlock, uint256 bal) = c.Acc(actor);
        assertTrue(bal == amount && unlock >= unlockTime || (unlock >= unlockTime && bal == amount));
    }
}
